-- Finite nonunique expression index. No function, guard, source, owner or history changes.
DO $index_preimage$
DECLARE actual_metadata jsonb;actual_foreign jsonb;
BEGIN
 SELECT (select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'body_sha256',encode(extensions.digest(convert_to(p.prosrc,'UTF8'),'sha256'),'hex'),
 'volatility',p.provolatile,'security_definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl) order by p.oid::regprocedure::text)
 from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace where n.nspname in('private','public') and
 (p.proname like 'awardping_pappg_canonical_%' or p.proname like 'awardping_program_text_canonical_%'
 or p.proname in('prepare_program_text_pappg_canonical','prepare_program_text_source','get_program_text_source_pending_capture',
  'awardping_program_source_pending_valid','awardping_program_source_approval_document_valid','awardping_program_raw_anchor_provider_link_valid'))) INTO actual_metadata;
 IF actual_metadata IS DISTINCT FROM $pappg_index_function_preimages_v1$[{"acl":["postgres=X/postgres","service_role=X/postgres"],"config":["search_path=\"\""],"signature":"get_program_text_source_pending_capture(uuid)","volatility":"s","body_sha256":"d85ff2fb3a6d816e340d1cad6331df42a423f7569520e5eb1f2f1b40559f3aa1","security_definer":false},{"acl":["postgres=X/postgres","service_role=X/postgres"],"config":["search_path=\"\""],"signature":"prepare_program_text_pappg_canonical(jsonb,jsonb,jsonb,text)","volatility":"v","body_sha256":"0a813e4dec5f8d256f6bfda1214b5581900b630f499f108dc818342f06992993","security_definer":true},{"acl":["postgres=X/postgres","service_role=X/postgres"],"config":["search_path=\"\""],"signature":"prepare_program_text_source(jsonb,jsonb,text)","volatility":"v","body_sha256":"3c944e5acb117d1856f730f15680f2704b1501297e4516292bcd1eb3d1c5f7c7","security_definer":true},{"acl":["postgres=X/postgres","service_role=X/postgres"],"config":["search_path=\"\""],"signature":"private.awardping_pappg_canonical_admission_allowed(uuid,text,uuid)","volatility":"s","body_sha256":"606c39e367cfe67ccc3aee557016b8144ecb5a3d08540eb4b05d6d9cf4a1a970","security_definer":false},{"acl":["postgres=X/postgres","service_role=X/postgres"],"config":["search_path=\"\""],"signature":"private.awardping_pappg_canonical_boundary_current(uuid,boolean)","volatility":"s","body_sha256":"aeb1036eec522865fb3bddec4596cfa86c0e893b99d1ce16f5973baed95ab929","security_definer":false},{"acl":["postgres=X/postgres","service_role=X/postgres"],"config":["search_path=\"\""],"signature":"private.awardping_pappg_canonical_catalogue()","volatility":"i","body_sha256":"548f831d06fa559b9f16e3bfdd2c923a464262466c2676201b106d69d4ce1f47","security_definer":false},{"acl":["postgres=X/postgres","service_role=X/postgres"],"config":["search_path=\"\""],"signature":"private.awardping_pappg_canonical_context(uuid)","volatility":"s","body_sha256":"b271cd0f62eda749c3e13d9dfe5d74d0fa5dca45d7113e2c35811762ceef4ea8","security_definer":false},{"acl":["postgres=X/postgres"],"config":["search_path=\"\""],"signature":"private.awardping_pappg_canonical_disposition_immutable()","volatility":"v","body_sha256":"fec19eb7f24d8e335dcb9e0b9befbaf64acd2566f462096ab74ebd83088fd511","security_definer":true},{"acl":["postgres=X/postgres","service_role=X/postgres"],"config":["search_path=\"\""],"signature":"private.awardping_pappg_canonical_foreign_projection(uuid)","volatility":"s","body_sha256":"86ce093d67b1077f81002d0049cfb52af08b6f040c7e6174bf64b0d28897618d","security_definer":false},{"acl":["postgres=X/postgres","service_role=X/postgres"],"config":["search_path=\"\""],"signature":"private.awardping_pappg_canonical_known(uuid,text)","volatility":"i","body_sha256":"95398a6b630485b5045211173bf40d1f25c64d36fdba1e9d991e3e2222512277","security_definer":false},{"acl":["postgres=X/postgres","service_role=X/postgres"],"config":["search_path=\"\""],"signature":"private.awardping_pappg_canonical_page_metadata_hash(jsonb)","volatility":"i","body_sha256":"6492b49ca18163b5ec77d3c0eeff56bb90c4e657d38891e7c295987dc4c494f5","security_definer":false},{"acl":["postgres=X/postgres","service_role=X/postgres"],"config":["search_path=\"\""],"signature":"private.awardping_pappg_canonical_prepare_guard(jsonb)","volatility":"s","body_sha256":"7b86b46ab59965a1a6c0546e98122eeb8a0b56bbae2f5812f06ac625dec6a202","security_definer":false},{"acl":["postgres=X/postgres"],"config":["search_path=\"\""],"signature":"private.awardping_pappg_canonical_source_fence()","volatility":"v","body_sha256":"0412382a7ec9c2b88dc038d9ee95367425654f0d24fcbe745b76040b48dc1869","security_definer":true},{"acl":["postgres=X/postgres","service_role=X/postgres"],"config":["search_path=\"\""],"signature":"private.awardping_pappg_canonical_url_key(text)","volatility":"i","body_sha256":"6645823392e4725df339a025212c35b66a3382826600389e2a3de3d2d61b0592","security_definer":false},{"acl":["postgres=X/postgres","service_role=X/postgres"],"config":["search_path=\"\""],"signature":"private.awardping_program_raw_anchor_provider_link_valid(jsonb,jsonb,jsonb)","volatility":"i","body_sha256":"c3dcb4e3065753b93bfa7c515db1212d167b4b1aecf3b4ba1d682a1a539945bd","security_definer":false},{"acl":["postgres=X/postgres","service_role=X/postgres"],"config":["search_path=\"\""],"signature":"private.awardping_program_source_approval_document_valid(jsonb)","volatility":"i","body_sha256":"28d177e66a6a3f54bdaa19926d5377c3d04eeec266cbbce01ec24bd189d118a6","security_definer":false},{"acl":["postgres=X/postgres","service_role=X/postgres"],"config":["search_path=\"\""],"signature":"private.awardping_program_source_pending_valid(jsonb)","volatility":"s","body_sha256":"4aac1b764f4c2e233b2a4a2e8b3d8d25080287ed34d2e4c45edd448990eeb187","security_definer":false},{"acl":["postgres=X/postgres","service_role=X/postgres"],"config":["search_path=\"\""],"signature":"private.awardping_program_text_canonical_boundary_current(uuid,text,uuid,text,jsonb)","volatility":"s","body_sha256":"3dbddf4bbf59f901f9ed5833035b4ae0084af252ad2758d96cac9b84f04a2167","security_definer":false},{"acl":["postgres=X/postgres","service_role=X/postgres"],"config":["search_path=\"\""],"signature":"private.awardping_program_text_canonical_boundary_dispatch(uuid,text,uuid,text,boolean)","volatility":"s","body_sha256":"e3624176a9dd84778b32e5837d5b06a708fd2b7f588f49a84614d5b252f9af8a","security_definer":false},{"acl":["postgres=X/postgres","service_role=X/postgres"],"config":["search_path=\"\""],"signature":"private.awardping_program_text_canonical_proof_hash(jsonb,jsonb)","volatility":"s","body_sha256":"e7e06d2116fb650996b79fd4348c2e28a783971efba8dbd7ece577c249ecc1f8","security_definer":false},{"acl":["postgres=X/postgres","service_role=X/postgres"],"config":["search_path=\"\""],"signature":"private.awardping_program_text_canonical_url_admission(uuid,uuid)","volatility":"s","body_sha256":"905382f8f285e43a4287c15c339b6ad0ce5d60f665322e7953a9b11e877ce950","security_definer":false}]$pappg_index_function_preimages_v1$::jsonb THEN RAISE EXCEPTION 'Reviewed PAPPG function bodies/ACL/config changed.' USING ERRCODE='40001';END IF;
 SELECT (select jsonb_agg(jsonb_build_object('id',s.id,'owner',s.shared_award_id,'url',s.url,'xmin',s.xmin::text,'ctid',s.ctid::text,
 'whole_row_sha256',encode(extensions.digest(convert_to(to_jsonb(s)::text,'UTF8'),'sha256'),'hex')) order by s.id)
 from public.shared_award_sources s join private.awardping_pappg_canonical_catalogue() c on c.source_id=s.id) INTO actual_foreign;
 IF actual_foreign IS DISTINCT FROM $pappg_index_foreign_preimages_v1$[{"id":"19204933-2b56-42ac-96ee-b54213a2785a","url":"https://www.nsf.gov/policies/pappg","ctid":"(4470,4)","xmin":"850986","owner":"c9b26239-8177-445b-ab39-473bc0c14d8f","whole_row_sha256":"071db2b01c5f25e1cfb52b56cc63ef90acdf403458bfe181c3dbc82a80748b4d"},{"id":"27a2e7e7-d679-4b60-a9fb-300bbe33a94c","url":"https://www.nsf.gov/policies/pappg","ctid":"(1641,8)","xmin":"572425","owner":"e4087bdf-e170-43a8-a1d1-6f6cead31eb4","whole_row_sha256":"bc880b3c94ff8b67272316bced1e4cc430c3f8d46f1fd25c10ad2a6a9bbed082"},{"id":"29839757-599c-4758-873f-974380ca7e9d","url":"https://www.nsf.gov/policies/pappg","ctid":"(822,8)","xmin":"546685","owner":"36ddccfa-b6a2-414c-b955-6a56b269148f","whole_row_sha256":"f329f9c78989ebf00d50276c768fdfed64d7763990c71495e385e2d22946cb21"},{"id":"3e5795a6-d0d0-4894-af01-b1abcfdee999","url":"https://www.nsf.gov/policies/pappg","ctid":"(2159,19)","xmin":"572425","owner":"c2771e8a-9328-47ca-a15b-871f27178b1d","whole_row_sha256":"80e38f22252fb8e9f90c637246f0936b09ae39d0d9848b28734408a57e123bd8"},{"id":"5a952e53-9c66-4c0f-9c42-07eaef865011","url":"https://www.nsf.gov/policies/pappg","ctid":"(4551,1)","xmin":"851239","owner":"2208c57b-6bde-44da-8c9e-6461c607ffe9","whole_row_sha256":"04a27a760b9ff264f884a6d6199ce507fc4282ff2d97ebf1db8e47c87716db40"},{"id":"73e4e932-cf63-47c4-a929-11a50e170728","url":"https://www.nsf.gov/policies/pappg","ctid":"(4725,5)","xmin":"851316","owner":"b752360f-b17b-4e19-acbd-28ec4222a9d6","whole_row_sha256":"2a3ae6717a1826a40d0eac314e56fb4e50db9e8fa784048ba004a19d1c7389d6"},{"id":"8ff84135-5a09-4873-ab89-28129e5d9cbf","url":"https://www.nsf.gov/policies/pappg","ctid":"(5749,9)","xmin":"783199","owner":"017d5a96-6121-4353-b094-985080a3f84e","whole_row_sha256":"05154615952459b2a79efcfe8636cad2a8cff96b6ddb5021212e7dfed9b0ddde"},{"id":"a04ebac4-827b-423d-a79f-8bfdd5e24008","url":"https://www.nsf.gov/policies/pappg","ctid":"(3790,8)","xmin":"850343","owner":"3a091e