 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_proc p WHERE p.oid='private.awardping_pappg_canonical_url_key(text)'::regprocedure
  AND p.provolatile='i' AND NOT p.prosecdef AND encode(extensions.digest(convert_to(p.prosrc,'UTF8'),'sha256'),'hex')='6645823392e4725df339a025212c35b66a3382826600389e2a3de3d2d61b0592')
  OR pg_catalog.to_regclass('public.shared_award_sources_pappg_canonical_url_key_idx') IS NOT NULL THEN
  RAISE EXCEPTION 'Exact immutable normalizer or unused index identity changed.' USING ERRCODE='40001';END IF;
END $index_preimage$;
CREATE INDEX shared_award_sources_pappg_canonical_url_key_idx
 ON public.shared_award_sources (private.awardping_pappg_canonical_url_key(url))
 WHERE private.awardping_pappg_canonical_url_key(url)='https://www.nsf.gov/policies/pappg';
